            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: TransportException -> FfiConverterTypeTransportError.lower(e) }
            )
        }
    }
    internal object `recv`: UniffiCallbackInterfaceTransportMethod1 {
